// Echo 模拟类
class EchoSimulator {
  private assets: MockAsset[]
  private usageLogs: any[]
  private derivativeRequests: any[]
  private extensionRequests: any[]

  constructor() {
    this.assets = [...mockAssets]
    this.usageLogs = []
    this.derivativeRequests = []
    this.extensionRequests = []
  }

  // 资产操作
  async mint(metadataURI: string, signer: string): Promise<string> {
    const tokenId = `ECHO-${(this.assets.length + 1).toString().padStart(3, '0')}`
    const newAsset: MockAsset = {
      tokenId,
      owner: signer,
      metadataURI,
      isActive: true,
      rentalInfo: {
        rentalType: 0,
        pricePerUse: ethers.parseEther('0.01'),
        remainingUses: BigInt(1000),
      },
      derivTerms: {
        allowed: true,
        upfrontFee: ethers.parseEther('0.1'),
        usageRoyalty: 15,
      },
      extConfig: {
        extensible: true,
        mode: 1,
        maxSceneRevenueShare: 25,
      },
    }
    this.assets.push(newAsset)
    return tokenId
  }

  async ownerOf(tokenId: string): Promise<string> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    return asset?.owner || '0x0000000000000000000000000000000000000000'
  }

  async userOf(tokenId: string): Promise<string> {
    // 模拟用户使用
    return '0x14723a09acff6d2a60dcdf7aa4aff308fddc160c'
  }

  async getRemainingTimes(tokenId: string): Promise<bigint> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    return asset?.rentalInfo.remainingUses || BigInt(0)
  }

  async getAssetInfo(tokenId: string): Promise<MockAsset | undefined> {
    return this.assets.find(a => a.tokenId === tokenId)
  }

  async getAssets(): Promise<MockAsset[]> {
    return [...this.assets]
  }

  // 使用操作
  async useECHO(tokenId: string, user: string, params?: string): Promise<RevenueDistribution> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    // 模拟使用消耗
    if (asset.rentalInfo.rentalType === 0 && asset.rentalInfo.remainingUses) {
      asset.rentalInfo.remainingUses--
    }

    // 计算收益分配
    const price = asset.rentalInfo.pricePerUse || ethers.parseEther('0.01')
    const creatorShare = BigInt(Math.floor(Number(price) * REVENUE_SHARE.creator))
    const protocolShare = BigInt(Math.floor(Number(price) * REVENUE_SHARE.protocol))
    const ecosystemShare = BigInt(Math.floor(Number(price) * REVENUE_SHARE.ecosystem))

    const distribution: RevenueDistribution = {
      creator: creatorShare,
      protocol: protocolShare,
      ecosystem: ecosystemShare,
    }

    // 记录使用日志
    this.usageLogs.push({
      tokenId,
      user,
      params,
      timestamp: Date.now(),
      distribution,
    })

    return distribution
  }

  // 租赁操作
  async rentEcho(tokenId: string, renter: string, duration: number): Promise<void> {
    // 模拟租赁操作
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    // 记录租赁信息
    this.usageLogs.push({
      tokenId,
      renter,
      duration,
      timestamp: Date.now(),
      type: 'rental',
    })
  }

  async getRentalInfo(tokenId: string): Promise<any> {
    return {
      rentalType: 0,
      pricePerUse: ethers.parseEther('0.01'),
      remainingUses: BigInt(847),
    }
  }

  async updateRentalInfo(tokenId: string, owner: string, rentalType: 0 | 1, price: bigint): Promise<void> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    if (asset.owner !== owner) {
      throw new Error('Not owner')
    }

    asset.rentalInfo.rentalType = rentalType
    if (rentalType === 0) {
      asset.rentalInfo.pricePerUse = price
    } else {
      asset.rentalInfo.pricePerMinute = price
    }
  }

  // 衍生操作
  async setDerivTerms(tokenId: string, owner: string, upfrontFee: bigint, usageRoyalty: number): Promise<void> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    if (asset.owner !== owner) {
      throw new Error('Not owner')
    }

    asset.derivTerms.upfrontFee = upfrontFee
    asset.derivTerms.usageRoyalty = usageRoyalty
  }

  async requestAsDerivative(parentId: string, requester: string, derivedName: string): Promise<bigint> {
    const requestId = BigInt(this.derivativeRequests.length + 1)
    this.derivativeRequests.push({
      requestId,
      parentId,
      requester,
      derivedName,
      status: 'PENDING',
      timestamp: Date.now(),
    })
    return requestId
  }

  async approveDerivativeRequest(parentId: string, requestId: bigint): Promise<string> {
    const request = this.derivativeRequests.find(r => r.requestId === requestId)
    if (!request) {
      throw new Error('Request not found')
    }

    request.status = 'APPROVED'
    return `DERIV-${requestId}`
  }

  async rejectDerivativeRequest(requestId: bigint): Promise<void> {
    const request = this.derivativeRequests.find(r => r.requestId === requestId)
    if (!request) {
      throw new Error('Request not found')
    }

    request.status = 'REJECTED'
  }

  // 扩展操作
  async setExtensible(tokenId: string, owner: string, extensible: boolean, mode: 0 | 1, maxSceneRevenueShare: number): Promise<void> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    if (asset.owner !== owner) {
      throw new Error('Not owner')
    }

    asset.extConfig.extensible = extensible
    asset.extConfig.mode = mode
    asset.extConfig.maxSceneRevenueShare = maxSceneRevenueShare
  }

  async approvePermission(tokenId: string, owner: string, grantee: string, scene: string): Promise<void> {
    const asset = this.assets.find(a => a.tokenId === tokenId)
    if (!asset) {
      throw new Error('Asset not found')
    }

    if (asset.owner !== owner) {
      throw new Error('Not owner')
    }

    // 记录授权信息
    this.extensionRequests.push({
      tokenId,
      grantee,
      scene,
      status: 'APPROVED',
      timestamp: Date.now(),
    })
  }

  async requestPermission(tokenId: string, requester: string, scene: string, proposedRevenueShare: number, reason: string): Promise<bigint> {
    const requestId = BigInt(this.extensionRequests.length + 1)
    this.extensionRequests.push({
      requestId,
      tokenId,
      requester,
      scene,
      proposedRevenueShare,
      reason,
      status: 'PENDING',
      timestamp: Date.now(),
    })
    return requestId
  }

  async useECHOOf(tokenId: string, user: string, scene: string, params?: string): Promise<RevenueDistribution> {
    return this.useECHO(tokenId, user, params)
  }

  // 查询操作
  async getUsageLogs(limit?: number): Promise<any[]> {
    return limit ? this.usageLogs.slice(-limit) : this.usageLogs
  }

  async getStats(): Promise<any> {
    return {
      totalAssets: this.assets.length,
      activeAssets: this.assets.filter(a => a.isActive).length,
      totalUsage: this.usageLogs.length,
      totalRevenue: ethers.parseEther('15.87'),
    }
  }
}

