import { echoSimulator, MockAsset } from './echoSimulator'

// 类型定义
export interface ExecutionRequest {
  userAddress: string
  request: string
  preferredRights?: RightType[]
}

export type RightType = 'Ownership' | 'Usage' | 'Derivative' | 'Extension'

export type VerdictType = 'APPROVED' | 'DENIED' | 'CONDITIONAL' | 'PENDING_APPROVAL'

export interface ExecutionVerdict {
  verdict: VerdictType
  message: string
  conditions?: string[]
  settlementPlan?: SettlementPlan
  requiredActions?: string[]
}

export interface SettlementPlan {
  type: 'immediate' | 'rental' | 'subscription'
  amount: bigint
  breakdown: {
    creator: bigint
    protocol: bigint
    ecosystem: bigint
    parentRoyalties?: bigint
    sceneBeneficiary?: bigint
  }
}

export interface RoutingResult {
  success: boolean
  matchedSkill?: CapabilityMatch
  alternatives?: CapabilityMatch[]
  estimatedCost?: bigint
  verdict: ExecutionVerdict
}

export interface CapabilityMatch {
  asset: MockAsset
  confidence: number
  matchedCapabilities: string[]
  missingCapabilities: string[]
  estimatedCost: bigint
}

// Agent 执行引擎类
class AgentExecutionEngine {
  private agentId: string
  private executionCount: number

  constructor() {
    this.agentId = 'EchoNexus-Engine-v1'
    this.executionCount = 0
  }

  // 辅助函数：提取关键词
  private extractKeywords(request: string): string[] {
    return request.toLowerCase().split(/\s+/).filter(word => word.length > 2)
  }

  // 辅助函数：计算匹配分数
  private calculateMatchScore(asset: MockAsset, keywords: string[], preferredRights?: RightType[]): number {
    let score = 0

    // 基础匹配（基于 metadataURI）
    if (asset.metadataURI.includes('legal')) {
      score += 20
    }
    if (asset.metadataURI.includes('analysis')) {
      score += 15
    }
    if (asset.metadataURI.includes('code')) {
      score += 15
    }
    if (asset.metadataURI.includes('review')) {
      score += 10
    }

    // 关键词匹配
    keywords.forEach(keyword => {
      if (asset.metadataURI.includes(keyword)) {
        score += 10
      }
    })

    // 权限匹配
    if (preferredRights?.includes('Usage')) {
      score += 5
    }
    if (preferredRights?.includes('Derivative')) {
      score += 3
    }

    return Math.min(100, score)
  }

  // 能力路由
  async routeRequest(
    userAddress: string,
    request: string,
    preferredRights?: RightType[]
  ): Promise<RoutingResult> {
    this.executionCount++

    try {
      // 提取关键词
      const keywords = this.extractKeywords(request)

      // 获取所有可用资产
      const assets = await echoSimulator.getAssets()
      const activeAssets = assets.filter(asset => asset.isActive)

      // 匹配能力
      const matches = activeAssets.map(asset => {
        const confidence = this.calculateMatchScore(asset, keywords, preferredRights)
        const matchedCapabilities = keywords.filter(keyword => asset.metadataURI.includes(keyword))
        const missingCapabilities = keywords.filter(keyword => !asset.metadataURI.includes(keyword))
        const estimatedCost = asset.rentalInfo.pricePerUse || BigInt(0)

        return {
          asset,
          confidence,
          matchedCapabilities,
          missingCapabilities,
          estimatedCost,
        }
      }).filter(match => match.confidence > 0)

      // 排序匹配结果
      matches.sort((a, b) => b.confidence - a.confidence)

      if (matches.length === 0) {
        return {
          success: false,
          verdict: {
            verdict: 'DENIED',
            message: 'No matching capabilities found',
          },
        }
      }

      // 最佳匹配
      const bestMatch = matches[0]
      const alternatives = matches.slice(1, 3)

      // 生成裁决
      const verdict = await this.checkPermissions(userAddress, {
        userAddress,
        request,
        preferredRights,
      })

      return {
        success: true,
        matchedSkill: bestMatch,
        alternatives,
        estimatedCost: bestMatch.estimatedCost,
        verdict,
      }
    } catch (error) {
      console.error('Routing error:', error)
      return {
        success: false,
        verdict: {
          verdict: 'DENIED',
          message: 'Routing failed',
        },
      }
    }
  }

  // 执行调度
  async execute(
    userAddress: string,
    tokenId: string,
    params?: string,
    scene?: string
  ): Promise<any> {
    try {
      // 检查权限
      const verdict = await this.checkPermissions(userAddress, {
        userAddress,
        request: '',
        preferredRights: ['Usage'],
      })

      if (verdict.verdict === 'DENIED') {
        throw new Error(`Permission denied: ${verdict.message}`)
      }

      // 执行能力
      const distribution = await echoSimulator.useECHO(tokenId, userAddress, params)

      return {
        success: true,
        tokenId,
        userAddress,
        params,
        scene,
        distribution,
        timestamp: Date.now(),
      }
    } catch (error) {
      console.error('Execution error:', error)
      return {
        success: false,
        error: error.message,
      }
    }
  }

  // 权限检查
  async checkPermissions(
    userAddress: string,
    request: ExecutionRequest
  ): Promise<ExecutionVerdict> {
    // 简化的权限检查逻辑
    // 实际应用中需要更复杂的裁决规则

    // 检查所有权
    const assets = await echoSimulator.getAssets()
    const userAssets = assets.filter(asset => asset.owner.toLowerCase() === userAddress.toLowerCase())

    if (userAssets.length > 0) {
      return {
        verdict: 'APPROVED',
        message: 'Owner permission granted',
      }
    }

    // 检查使用权
    // 这里简化处理，默认允许
    const settlementPlan: SettlementPlan = {
      type: 'immediate',
      amount: BigInt(10000000000000000), // 0.01 ETH
      breakdown: {
        creator: BigInt(8000000000000000), // 80%
        protocol: BigInt(1500000000000000), // 15%
        ecosystem: BigInt(500000000000000), // 5%
      },
    }

    return {
      verdict: 'CONDITIONAL',
      message: 'Payment required',
      conditions: ['Pay 0.01 ETH'],
      settlementPlan,
      requiredActions: ['Approve payment'],
    }
  }

  // 创建能力
  async createCapability(
    creator: string,
    name: string,
    description: string,
    capabilities: string[],
    pricing: { type: 'TimesBased' | 'DurationBased'; price: bigint }
  ): Promise<string> {
    try {
      // 生成 metadata URI
      const metadataURI = `ipfs://Qm${name.toLowerCase().replace(/\s+/g, '-')}/metadata.json`

      // 调用 mint 方法
      const tokenId = await echoSimulator.mint(metadataURI, creator)

      return tokenId
    } catch (error) {
      console.error('Capability creation error:', error)
      throw new Error('Failed to create capability')
    }
  }

  // 其他辅助方法
  async getExecutionHistory(userAddress: string, limit?: number): Promise<any[]> {
    const logs = await echoSimulator.getUsageLogs(limit)
    return logs.filter(log => log.user === userAddress)
  }

  async getExecutionStats(): Promise<any> {
    const logs = await echoSimulator.getUsageLogs()
    const stats = await echoSimulator.getStats()

    return {
      ...stats,
      totalUsage: logs.length,
      averageCost: BigInt(Math.floor(Number(stats.totalRevenue) / logs.length)),
    }
  }
}

