export const agentEngine = new AgentExecutionEngine()

import React, { useState } from 'react'
import { Play, Stop, RotateCcw, Zap, Brain, Activity } from 'lucide-react'
import { agentEngine } from '../../services/agentEngine'
import { echoSimulator } from '../../services/echoSimulator'

// 类型定义
interface ExecutionStep {
  id: string
  label: string
  status: 'pending' | 'active' | 'completed' | 'error'
  description: string
}

interface ExecutionResult {
  success: boolean
  data?: any
  error?: string
  duration?: number
}

const Executor: React.FC = () => {
  const [request, setRequest] = useState('')
  const [isExecuting, setIsExecuting] = useState(false)
  const [executionSteps, setExecutionSteps] = useState<ExecutionStep[]>([
    {
      id: 'route',
      label: '能力路由',
      status: 'pending',
      description: '分析请求并匹配最佳能力',
    },
    {
      id: 'permissions',
      label: '权限检查',
      status: 'pending',
      description: '验证用户权限和计费信息',
    },
    {
      id: 'execution',
      label: '执行',
      status: 'pending',
      description: '执行选中的 AI 能力',
    },
    {
      id: 'settlement',
      label: '结算',
      status: 'pending',
      description: '计算收益分配并更新状态',
    },
  ])
  const [result, setResult] = useState<ExecutionResult | null>(null)

  // 更新步骤状态
  const updateStepStatus = (stepId: string, status: ExecutionStep['status']) => {
    setExecutionSteps(prev =>
      prev.map(step =>
        step.id === stepId ? { ...step, status } : step
      )
    )
  }

  // 执行能力
  const executeCapability = async () => {
    if (!request.trim()) {
      alert('请输入请求内容')
      return
    }

    setIsExecuting(true)
    setResult(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )

    try {
      // 1. 能力路由
      updateStepStatus('route', 'active')
      const routingResult = await agentEngine.routeRequest(
        '0x7a250d5630b4cf539739df2c5dacb4c659f2488d',
        request
      )

      if (!routingResult.success) {
        updateStepStatus('route', 'error')
        throw new Error(routingResult.verdict.message)
      }

      updateStepStatus('route', 'completed')

      // 2. 权限检查
      updateStepStatus('permissions', 'active')
      const verdict = await agentEngine.checkPermissions(
        '0x7a250d5630b4cf539739df2c5dacb4c659f2488d',
        {
          userAddress: '0x7a250d5630b4cf539739df2c5dacb4c659f2488d',
          request,
        }
      )

      if (verdict.verdict === 'DENIED') {
        updateStepStatus('permissions', 'error')
        throw new Error(verdict.message)
      }

      updateStepStatus('permissions', 'completed')

      // 3. 执行
      updateStepStatus('execution', 'active')
      const executionResult = await agentEngine.execute(
        '0x7a250d5630b4cf539739df2c5dacb4c659f2488d',
        routingResult.matchedSkill?.asset.tokenId || 'ECHO-001'
      )

      if (!executionResult.success) {
        updateStepStatus('execution', 'error')
        throw new Error(executionResult.error)
      }

      updateStepStatus('execution', 'completed')

      // 4. 结算
      updateStepStatus('settlement', 'active')
      await new Promise(resolve => setTimeout(resolve, 800)) // 模拟结算延迟

      updateStepStatus('settlement', 'completed')

      // 显示结果
      setResult({
        success: true,
        data: {
          matchedSkill: routingResult.matchedSkill,
          verdict,
          distribution: executionResult.distribution,
        },
        duration: Math.floor(Math.random() * 3000) + 1000,
      })
    } catch (error) {
      console.error('Execution error:', error)
      setResult({
        success: false,
        error: error instanceof Error ? error.message : '执行失败',
      })
    } finally {
      setIsExecuting(false)
    }
  }

  // 停止执行
  const stopExecution = () => {
    setIsExecuting(false)
    setResult(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )
  }

  // 重置执行
  const resetExecution = () => {
    setIsExecuting(false)
    setResult(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )
    setRequest('')
  }

  return (
    <div className="space-y-6">
      {/* 标题 */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Agent 执行器</h1>
          <p className="mt-1 text-sm text-gray-600">
            输入请求，AI 会自动匹配并执行最佳能力
          </p>
        </div>
      </div>

      {/* 请求输入 */}
      <div className="bg-white rounded-lg shadow p-6">
        <div className="flex items-start space-x-4">
          <div className="flex-shrink-0 mt-1">
            <Brain className="h-6 w-6 text-primary-600" />
          </div>
          <div className="flex-1">
            <label
