// API 和工具函数

import { ethers } from 'ethers'

// 格式化 ETH 值
export const formatETH = (value: bigint): string => {
  try {
    return ethers.formatEther(value)
  } catch (error) {
    console.error('Failed to format ETH:', error)
    return '0.00'
  }
}

// 解析 ETH 值
export const parseETH = (value: string): bigint => {
  try {
    return ethers.parseEther(value)
  } catch (error) {
    console.error('Failed to parse ETH:', error)
    return BigInt(0)
  }
}

// 截断地址显示
export const truncateAddress = (address: string, start = 6, end = 4): string => {
  if (!address) return ''
  return `${address.slice(0, start + 2)}...${address.slice(-end)}`
}

// 格式化日期
export const formatDate = (timestamp: number): string => {
  const date = new Date(timestamp)
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

// 生成随机 ID
export const generateId = (): string => {
  return `id_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
}

// 防抖函数
export const debounce = <T extends (...args: any[]) => any>(
  func: T,
  wait: number
): ((...args: Parameters<T>) => void) => {
  let timeout: NodeJS.Timeout
  return (...args: Parameters<T>) => {
    clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }
}

// 节流函数
export const throttle = <T extends (...args: any[]) => any>(
  func: T,
  limit: number
): ((...args: Parameters<T>) => void) => {
  let lastCall = 0
  return (...args: Parameters<T>) => {
    const now = Date.now()
    if (now - lastCall >= limit) {
      func(...args)
      lastCall = now
    }
  }
}

// 格式化数字
export const formatNumber = (
  number: number | string,
  decimals = 2,
  thousandSeparator = ',',
  decimalSeparator = '.'
): string => {
  try {
    const num = typeof number === 'string' ? parseFloat(number) : number
    if (isNaN(num)) return '0'

    const parts = num.toFixed(decimals).split('.')
    const integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, thousandSeparator)
    const decimalPart = parts[1]

    return decimalPart ? `${integerPart}${decimalSeparator}${decimalPart}` : integerPart
  } catch (error) {
    console.error('Failed to format number:', error)
    return '0'
  }
}

// 验证地址格式
export const isValidAddress = (address: string): boolean => {
  return /^0x[a-fA-F0-9]{40}$/.test(address)
}

// 深拷贝对象
export const deepCopy = <T>(obj: T): T => {
  return JSON.parse(JSON.stringify(obj)) as T
}

// 合并对象
export const mergeObjects = <T extends Record<string, any>>(
  target: T,
  ...sources: T[]
): T => {
  return sources.reduce((result, source) => {
    return Object.keys(source).reduce((prev, key) => {
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        prev[key] = mergeObjects(
          prev[key] || {},
          source[key]
        )
      } else if (Array.isArray(source[key])) {
        prev[key] = [...(prev[key] || []), ...source[key]]
      } else {
        prev[key] = source[key]
      }
      return prev
    }, prev)
  }, deepCopy(target))
}

