  // 初始化数据
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [assetsData, statsData, logsData] = await Promise.all([
          echoSimulator.getAssets(),
          echoSimulator.getStats(),
          echoSimulator.getUsageLogs(),
        ])

        setAssets(assetsData)
        setStats(statsData)
        setUsageLogs(logsData)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to fetch data')
      } finally {
        setIsLoading(false)
      }
    }

    fetchData()
  }, [address])

  // 创建资产
  const mintAsset = useCallback(async (metadataURI: string): Promise<string> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      const tokenId = await echoSimulator.mint(metadataURI, address)

      // 更新资产列表
      const assetsData = await echoSimulator.getAssets()
      setAssets(assetsData)

      return tokenId
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to mint asset'
      setError(errorMessage)
      throw err
    }
  }, [address])

  // 使用资产
  const useAsset = useCallback(async (tokenId: string, params?: string): Promise<RevenueDistribution> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      const distribution = await echoSimulator.useECHO(tokenId, address, params)

      // 更新使用日志
      const logsData = await echoSimulator.getUsageLogs()
      setUsageLogs(logsData)

      return distribution
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to use asset'
      setError(errorMessage)
      throw err
    }
  }, [address])

  // 租赁资产
  const rentAsset = useCallback(async (tokenId: string, duration: number): Promise<void> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      await echoSimulator.rentEcho(tokenId, address, duration)

      // 更新使用日志
      const logsData = await echoSimulator.getUsageLogs()
      setUsageLogs(logsData)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to rent asset'
      setError(errorMessage)
      throw err
    }
  }, [address])

  // 获取资产信息
  const getAssetInfo = useCallback(async (tokenId: string): Promise<MockAsset | undefined> => {
    try {
      setError(null)
      return await echoSimulator.getAssetInfo(tokenId)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to get asset info'
      setError(errorMessage)
      return undefined
    }
  }, [])

  // 更新租赁信息
  const updateRentalInfo = useCallback(async (
    tokenId: string,
    rentalType: 0 | 1,
    price: bigint
  ): Promise<void> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      await echoSimulator.updateRentalInfo(tokenId, address, rentalType, price)

      // 更新资产列表
      const assetsData = await echoSimulator.getAssets()
      setAssets(assetsData)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update rental info'
      setError(errorMessage)
      throw err
    }
  }, [address])

  // 设置衍生条款
  const setDerivTerms = useCallback(async (
    tokenId: string,
    upfrontFee: bigint,
    usageRoyalty: number
  ): Promise<void> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      await echoSimulator.setDerivTerms(tokenId, address, upfrontFee, usageRoyalty)

      // 更新资产列表
      const assetsData = await echoSimulator.getAssets()
      setAssets(assetsData)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to set derivative terms'
      setError(errorMessage)
      throw err
    }
  }, [address])

  // 设置可扩展性
  const setExtensible = useCallback(async (
    tokenId: string,
    extensible: boolean,
    mode: 0 | 1,
    maxSceneRevenueShare: number
  ): Promise<void> => {
    if (!address) {
      throw new Error('Wallet not connected')
    }

    try {
      setError(null)
      await echoSimulator.setExtensible(tokenId, address, extensible, mode, maxSceneRevenueShare)

      // 更新资产列表
      const assetsData = await echoSimulator.getAssets()
      setAssets(assetsData)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to set extensible'
      setError(errorMessage)
      throw err
    }
  }, [address])

  return {
    assets,
    stats,
    usageLogs,
    isLoading,
    error,
    mintAsset,
    useAsset,
    rentAsset,
    getAssetInfo,
    updateRentalInfo,
    setDerivTerms,
    setExtensible,
  }
}

import { useState, useEffect, useCallback } from 'react'
import { agentEngine, ExecutionRequest, VerdictType, ExecutionVerdict, RoutingResult, ExecutionResult } from '../services/agentEngine'
import { useAccount } from 'wagmi'

// 类型定义
interface UseExecutionReturn {
  isExecuting: boolean
  executionSteps: ExecutionStep[]
  routingResult: RoutingResult | null
  verdict: ExecutionVerdict | null
  result: ExecutionResult | null
  execute: (request: string) => Promise<void>
  stop: () => void
  reset: () => void
  error: string | null
}

interface ExecutionStep {
  id: string
  label: string
  status: 'pending' | 'active' | 'completed' | 'error'
  description: string
}

const useExecution = (): UseExecutionReturn => {
  const { address } = useAccount()
  const [isExecuting, setIsExecuting] = useState(false)
  const [executionSteps, setExecutionSteps] = useState<ExecutionStep[]>([
    {
      id: 'route',
      label: '能力路由',
      status: 'pending',
      description: '分析请求并匹配最佳能力',
    },
    {
      id: 'permissions',
      label: '权限检查',
      status: 'pending',
      description: '验证用户权限和计费信息',
    },
    {
      id: 'execution',
      label: '执行',
      status: 'pending',
      description: '执行选中的 AI 能力',
    },
    {
      id: 'settlement',
      label: '结算',
      status: 'pending',
      description: '计算收益分配并更新状态',
    },
  ])
  const [routingResult, setRoutingResult] = useState<RoutingResult | null>(null)
  const [verdict, setVerdict] = useState<ExecutionVerdict | null>(null)
  const [result, setResult] = useState<ExecutionResult | null>(null)
  const [error, setError] = useState<string | null>(null)

  // 更新步骤状态
  const updateStepStatus = useCallback((stepId: string, status: ExecutionStep['status']) => {
    setExecutionSteps(prev =>
      prev.map(step =>
        step.id === stepId ? { ...step, status } : step
      )
    )
  }, [])

  // 执行能力
  const execute = useCallback(async (request: string) => {
    if (!address) {
      setError('Wallet not connected')
      return
    }

    if (!request.trim()) {
      setError('Please enter a request')
      return
    }

    setIsExecuting(true)
    setResult(null)
    setError(null)
    setRoutingResult(null)
    setVerdict(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )

    try {
      // 1. 能力路由
      updateStepStatus('route', 'active')
      const routingResultData = await agentEngine.routeRequest(
        address,
        request
      )

      if (!routingResultData.success) {
        updateStepStatus('route', 'error')
        setError(routingResultData.verdict.message)
        setIsExecuting(false)
        return
      }

      setRoutingResult(routingResultData)
      updateStepStatus('route', 'completed')

      // 2. 权限检查
      updateStepStatus('permissions', 'active')
      const verdictData = await agentEngine.checkPermissions(
        address,
        {
          userAddress: address,
          request,
        }
      )

      if (verdictData.verdict === 'DENIED') {
        updateStepStatus('permissions', 'error')
        setError(verdictData.message)
        setIsExecuting(false)
        return
      }

      setVerdict(verdictData)
      updateStepStatus('permissions', 'completed')

      // 3. 执行
      updateStepStatus('execution', 'active')
      const executionResultData = await agentEngine.execute(
        address,
        routingResultData.matchedSkill?.asset.tokenId || 'ECHO-001'
      )

      if (!executionResultData.success) {
        updateStepStatus('execution', 'error')
        setError(executionResultData.error)
        setIsExecuting(false)
        return
      }

      updateStepStatus('execution', 'completed')

      // 4. 结算
      updateStepStatus('settlement', 'active')
      await new Promise(resolve => setTimeout(resolve, 800)) // 模拟结算延迟

      updateStepStatus('settlement', 'completed')

      // 显示结果
      setResult({
        success: true,
        data: {
          matchedSkill: routingResultData.matchedSkill,
          verdict: verdictData,
          distribution: executionResultData.distribution,
        },
        duration: Math.floor(Math.random() * 3000) + 1000,
      })

      setIsExecuting(false)
    } catch (err) {
      console.error('Execution error:', err)
      const errorMessage = err instanceof Error ? err.message : 'Execution failed'
      setError(errorMessage)
      setIsExecuting(false)
      // 标记最后一个执行步骤为错误状态
      const activeStep = executionSteps.find(step => step.status === 'active')
      if (activeStep) {
        updateStepStatus(activeStep.id, 'error')
      }
    }
  }, [address, executionSteps])

  // 停止执行
  const stop = useCallback(() => {
    setIsExecuting(false)
    setError('Execution stopped')
    // 标记当前步骤为错误状态
    const activeStep = executionSteps.find(step => step.status === 'active')
    if (activeStep) {
      updateStepStatus(activeStep.id, 'error')
    }
  }, [executionSteps])

  // 重置状态
  const reset = useCallback(() => {
    setIsExecuting(false)
    setResult(null)
    setError(null)
    setRoutingResult(null)
    setVerdict(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )
  }, [])

  return {
    isExecuting,
    executionSteps,
    routingResult,
    verdict,
    result,
    execute,
    stop,
    reset,
    error,
  }
}

export default useExecution

