import React, { useState } from 'react'
import { Play, RotateCcw, Zap, Brain, Activity, Link as LinkIcon } from 'lucide-react'
import { Link } from 'react-router-dom'

// 类型定义
interface ExecutionStep {
  id: string
  label: string
  status: 'pending' | 'active' | 'completed' | 'error'
  description: string
}

interface ExecutionResult {
  success: boolean
  data?: any
  error?: string
  duration?: number
}

const Executor: React.FC = () => {
  const [request, setRequest] = useState('')
  const [isExecuting, setIsExecuting] = useState(false)
  const [executionSteps, setExecutionSteps] = useState<ExecutionStep[]>([
    {
      id: 'route',
      label: '能力路由',
      status: 'pending',
      description: '分析请求并匹配最佳能力',
    },
    {
      id: 'permissions',
      label: '权限检查',
      status: 'pending',
      description: '验证用户权限和计费信息',
    },
    {
      id: 'execution',
      label: '执行',
      status: 'pending',
      description: '执行选中的 AI 能力',
    },
    {
      id: 'settlement',
      label: '结算',
      status: 'pending',
      description: '计算收益分配并更新状态',
    },
  ])
  const [result, setResult] = useState<ExecutionResult | null>(null)

  // 更新步骤状态
  const updateStepStatus = (stepId: string, status: ExecutionStep['status']) => {
    setExecutionSteps(prev =>
      prev.map(step =>
        step.id === stepId ? { ...step, status } : step
      )
    )
  }

  // 执行能力
  const executeCapability = async () => {
    if (!request.trim()) {
      alert('请输入请求内容')
      return
    }

    setIsExecuting(true)
    setResult(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )

    try {
      // 1. 能力路由
      updateStepStatus('route', 'active')
      await new Promise(resolve => setTimeout(resolve, 1000))
      updateStepStatus('route', 'completed')

      // 2. 权限检查
      updateStepStatus('permissions', 'active')
      await new Promise(resolve => setTimeout(resolve, 800))
      updateStepStatus('permissions', 'completed')

      // 3. 执行
      updateStepStatus('execution', 'active')
      await new Promise(resolve => setTimeout(resolve, 1500))
      updateStepStatus('execution', 'completed')

      // 4. 结算
      updateStepStatus('settlement', 'active')
      await new Promise(resolve => setTimeout(resolve, 800))
      updateStepStatus('settlement', 'completed')

      // 显示结果
      setResult({
        success: true,
        data: {
          matchedSkill: {
            asset: { tokenId: 'ECHO-001', metadataURI: 'ipfs://QmXxx.../skill-legal-analysis.json' },
            confidence: 92,
          },
          verdict: { verdict: 'APPROVED', message: '执行成功' },
          distribution: {
            creator: 0.008,
            protocol: 0.0015,
            ecosystem: 0.0005,
          },
        },
        duration: Math.floor(Math.random() * 3000) + 1000,
      })

      setIsExecuting(false)
    } catch (error) {
      console.error('Execution error:', error)
      setResult({
        success: false,
        error: error instanceof Error ? error.message : '执行失败',
      })
      setIsExecuting(false)
    }
  }

  // 重置执行
  const resetExecution = () => {
    setIsExecuting(false)
    setResult(null)
    setExecutionSteps(prev =>
      prev.map(step => ({ ...step, status: 'pending' }))
    )
    setRequest('')
  }

  return (
    <div className="space-y-6 p-6">
      {/* 导航 */}
      <div className="flex items-center space-x-4">
        <Link to="/" className="flex items-center text-gray-600 hover:text-gray-900">
          <LinkIcon className="h-4 w-4 mr-2" />
          返回仪表板
        </Link>
      </div>

      {/* 标题 */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Agent 执行器</h1>
          <p className="mt-1 text-sm text-gray-600">
            输入请求，AI 会自动匹配并执行最佳能力
          </p>
        </div>
      </div>

      {/* 请求输入 */}
      <div className="bg-white rounded-lg shadow p-6">
        <div className="flex items-start space-x-4">
          <div className="flex-shrink-0 mt-1">
            <Brain className="h-6 w-6 text-blue-600" />
          </div>
          <div className="flex-1">
            <label
              htmlFor="request"
              className="block text-sm font-medium text-gray-700 mb-2"
            >
              请求内容
            </label>
            <textarea
              id="request"
              rows={3}
              value={request}
              onChange={(e) => setRequest(e.target.value)}
              placeholder="例如：分析智能合约的安全问题"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              disabled={isExecuting}
            />
          </div>
        </div>

        {/* 操作按钮 */}
        <div className="mt-4 flex justify-end space-x-3">
          {!isExecuting && (
            <button
              onClick={executeCapability}
              className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors disabled:opacity-50"
              disabled={!request.trim()}
            >
              <Play className="h-4 w-4 mr-2" />
              执行
            </button>
          )}

          {!isExecuting && result && (
            <button
              onClick={resetExecution}
              className="flex items-center px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors"
            >
              <RotateCcw className="h-4 w-4 mr-2" />
              重置
            </button>
          )}
        </div>
      </div>

      {/* 执行过程 */}
      {isExecuting && (
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-medium text-gray-900 mb-4">执行过程</h2>
          <div className="space-y-4">
            {executionSteps.map((step) => (
              <div key={step.id} className="flex items-center space-x-3">
                <div className="relative">
                  <div
                    className={`h-6 w-6 rounded-full flex items-center justify-center ${
                      step.status === 'completed'
                        ? 'bg-green-500 text-white'
                        : step.status === 'error'
                        ? 'bg-red-500 text-white'
                        : step.status === 'active'
                        ? 'bg-blue-500 text-white animate-pulse'
                        : 'bg-gray-200 text-gray-600'
                    }`}
                  >
                    {step.status === 'completed' ? (
                      <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                      </svg>
                    ) : step.status === 'error' ? (
                      <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    ) : (
                      <Activity className="h-4 w-4" />
                    )}
                  </div>
                  {step.status === 'active' && (
                    <div className="absolute inset-0 rounded-full border-2 border-blue-400 animate-ping"></div>
                  )}
                </div>

                <div className="flex-1">
                  <div className="flex items-center">
                    <span
                      className={`font-medium ${
                        step.status === 'completed' ? 'text-green-600' :
                        step.status === 'error' ? 'text-red-600' :
                        step.status === 'active' ? 'text-blue-600' : 'text-gray-500'
                      }`}
                    >
                      {step.label}
                    </span>
                    {step.status === 'active' && (
                      <span className="ml-2 text-xs text-blue-600 animate-pulse">
                        处理中...
                      </span>
                    )}
                  </div>
                  <div className="text-sm text-gray-500 mt-0.5">
                    {step.description}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 执行结果 */}
      {result && (
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-medium text-gray-900 mb-4">
            {result.success ? '执行成功' : '执行失败'}
          </h2>

          {result.success ? (
            <div className="space-y-4">
              {/* 执行结果 */}
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <div className="flex items-start space-x-3">
                  <div className="flex-shrink-0 mt-0.5">
                    <Zap className="h-5 w-5 text-green-600" />
                  </div>
                  <div className="flex-1">
                    <h3 className="font-medium text-green-800">执行结果</h3>
                    <p className="mt-1 text-sm text-green-700">
                      能力已成功执行，产生了以下收益分配：
                    </p>
                  </div>
                </div>
              </div>

              {/* 收益分配 */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <p className="text-sm font-medium text-blue-800">创作者收益</p>
                  <p className="text-2xl font-bold text-blue-600">
                    {result.data?.distribution?.creator} ETH
                  </p>
                </div>

                <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
                  <p className="text-sm font-medium text-purple-800">协议收益</p>
                  <p className="text-2xl font-bold text-purple-600">
                    {result.data?.distribution?.protocol} ETH
                  </p>
                </div>

                <div className="bg-orange-50 border border-orange-200 rounded-lg p-4">
                  <p className="text-sm font-medium text-orange-800">生态收益</p>
                  <p className="text-2xl font-bold text-orange-600">
                    {result.data?.distribution?.ecosystem} ETH
                  </p>
                </div>
              </div>

              {/* 匹配信息 */}
              <div className="border border-gray-200 rounded-lg p-4">
                <h3 className="font-medium text-gray-900 mb-2">匹配的能力</h3>
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center">
                    <Brain className="h-5 w-5 text-blue-600" />
                  </div>
                  <div>
                    <p className="font-medium text-gray-900">
                      {result.data?.matchedSkill?.asset.tokenId}
                    </p>
                    <p className="text-sm text-gray-500">
                      {result.data?.matchedSkill?.asset.metadataURI}
                    </p>
                  </div>
                  <div className="ml-auto">
                    <span className="px-2 py-1 text-xs font-medium bg-green-100 text-green-800 rounded-full">
                      匹配度: {result.data?.matchedSkill?.confidence}%
                    </span>
                  </div>
                </div>
              </div>

              {/* 执行时间 */}
              <div className="text-right">
                <p className="text-sm text-gray-500">
                  执行时间: {result.duration}ms
                </p>
              </div>
            </div>
          ) : (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4">
              <div className="flex items-start space-x-3">
                <div className="flex-shrink-0 mt-0.5">
                  <svg className="h-5 w-5 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </div>
                <div className="flex-1">
                  <h3 className="font-medium text-red-800">执行失败</h3>
                  <p className="mt-1 text-sm text-red-700">
                    {result.error}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

